package com.example.rokidgeminisecretary;
import org.json.*;import java.security.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** A single in-memory geometry snapshot; legacy messages remain complete and unchanged. */
public final class NavigationGeometryDelta {
 static boolean geometry(String key){return key.equals("route")||key.equals("wholeRoute")||key.equals("routeSegments")||key.equals("referenceRoute");}
 static String digest(String value)throws Exception{byte[] bytes=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte v:bytes)b.append(String.format(java.util.Locale.ROOT,"%02x",v&255));return b.toString();}
 static void canonical(Object value,StringBuilder out)throws Exception{if(value==null||value==JSONObject.NULL){out.append("null");return;}if(value instanceof JSONObject){JSONObject object=(JSONObject)value;ArrayList<String> keys=new ArrayList<>();Iterator<String> it=object.keys();while(it.hasNext())keys.add(it.next());Collections.sort(keys);out.append('{');for(String key:keys){out.append(JSONObject.quote(key)).append(':');canonical(object.get(key),out);out.append(',');}out.append('}');}else if(value instanceof JSONArray){out.append('[');JSONArray array=(JSONArray)value;for(int i=0;i<array.length();i++){canonical(array.get(i),out);out.append(',');}out.append(']');}else if(value instanceof Number)out.append(new java.math.BigDecimal(value.toString()).stripTrailingZeros().toPlainString());else if(value instanceof Boolean)out.append(value.toString());else out.append(JSONObject.quote(value.toString()));}
 static String scope(JSONObject packet)throws Exception{JSONObject selected=new JSONObject();for(String key:new String[]{"source","sdkSessionId","routeDestination","routeMode","routeGeneration","routeTime","phase"})selected.put(key,packet.opt(key)==null?JSONObject.NULL:packet.opt(key));StringBuilder b=new StringBuilder();canonical(selected,b);return b.toString();}
 static String identity(JSONObject packet,JSONObject parts)throws Exception{StringBuilder b=new StringBuilder(scope(packet));canonical(parts,b);return b.toString();}
 static void extract(JSONObject object,String path,JSONObject parts,int depth)throws Exception{if(depth>8)throw new JSONException("geometry nesting");ArrayList<String> keys=new ArrayList<>();Iterator<String> it=object.keys();while(it.hasNext())keys.add(it.next());for(String key:keys){Object value=object.opt(key);if(geometry(key)&&value instanceof JSONArray){parts.put(path+"/"+key,value);object.remove(key);}else if(value instanceof JSONObject)extract((JSONObject)value,path+"/"+key,parts,depth+1);}}
 static void restore(JSONObject object,JSONObject parts)throws Exception{if(parts.length()>64)throw new JSONException("geometry count");Iterator<String> it=parts.keys();while(it.hasNext()){String path=it.next();String[] keys=path.split("/");if(!path.startsWith("/")||keys.length<2||keys.length>10||!geometry(keys[keys.length-1])||!(parts.opt(path) instanceof JSONArray))throw new JSONException("invalid geometry path");JSONObject parent=object;for(int i=1;i<keys.length-1;i++){if(!keys[i].matches("[A-Za-z][A-Za-z0-9_]*"))throw new JSONException("invalid geometry parent");parent=parent.getJSONObject(keys[i]);}parent.put(keys[keys.length-1],parts.getJSONArray(path));}}
 public static final class Encoder {
  private String prior="",id="";private long full,delta;private int fullBytes,deltaBytes;
  public synchronized JSONObject encode(JSONObject input,String known)throws Exception{JSONObject packet=new JSONObject(input.toString());JSONObject parts=new JSONObject();extract(packet,"",parts,0);String value=scope(packet)+parts.toString();if(!value.equals(prior)){prior=value;id=digest(identity(packet,parts));}JSONObject transport=new JSONObject().put("version",1).put("geometryId",id);if(!id.equals(known)){transport.put("parts",parts);full++;}else delta++;packet.put("navigationDelta",transport);return packet;}
  public synchronized void notePacketBytes(int bytes,boolean fullPacket){if(fullPacket)fullBytes=Math.max(0,bytes);else deltaBytes=Math.max(0,bytes);}
  public synchronized JSONObject stats()throws Exception{return new JSONObject().put("fullPackets",full).put("deltaPackets",delta).put("lastFullBytes",fullBytes).put("lastDeltaBytes",deltaBytes).put("retainedGeometrySnapshots",prior.isEmpty()?0:1);}
 }
 public static final class MissingGeometry extends Exception {public MissingGeometry(){super("geometry full refresh required");}}
 public static final class Decoder {
  private String id="",context="";private JSONObject cachedParts;
  public synchronized String known(){return id;}
  public synchronized void clear(){id=context="";cachedParts=null;}
  public synchronized JSONObject decode(JSONObject packet)throws Exception{JSONObject transport=packet.optJSONObject("navigationDelta");if(transport==null){clear();return packet;}String next=transport.optString("geometryId");if(transport.optInt("version")!=1||!next.matches("[a-f0-9]{64}")){clear();throw new MissingGeometry();}JSONObject parts=transport.optJSONObject("parts");if(parts!=null){if(!digest(identity(packet,parts)).equals(next)){clear();throw new MissingGeometry();}try{restore(packet,parts);}catch(Exception e){clear();throw new MissingGeometry();}id=next;cachedParts=parts;context=scope(packet);}else{if(!id.equals(next)||cachedParts==null||!context.equals(scope(packet))){clear();throw new MissingGeometry();}try{restore(packet,cachedParts);}catch(Exception e){clear();throw new MissingGeometry();}}packet.remove("navigationDelta");return packet;}
 }
}
